          solution: "class ListNode {\n  constructor(value) {\n    this.value = value;\n    this.next = null;\n  }\n}\n\nclass LinkedList {\n  constructor() {\n    this.head = null;\n    this.size = 0;\n  }\n\n  prepend(value) {\n    const node = new ListNode(value);\n    node.next = this.head;\n    this.head = node;\n    this.size += 1;\n  }\n\n  append(value) {\n    const node = new ListNode(value);\n    this.size += 1;\n    if (this.head === null) {\n      this.head = node;\n      return;\n    }\n    let current = this.head;\n    while (current.next !== null) {\n      current = current.next;\n    }\n    current.next = node;\n  }\n\n  insertAfter(node, value) {\n    const fresh = new ListNode(value);\n    fresh.next = node.next;\n    node.next = fresh;\n    this.size += 1;\n  }\n\n  insertAt(index, value) {\n    if (index < 0 || index > this.size) {\n      return false;\n    }\n    if (index === 0) {\n      this.prepend(value);\n      return true;\n    }\n    let before = this.head;\n    for (let i = 1; i < index; i += 1) {\n      before = before.next;\n    }\n    this.insertAfter(before, value);\n    return true;\n  }\n\n  toArray() {\n    const values = [];\n    let current = this.head;\n    while (current !== null) {\n      values.push(current.value);\n      current = current.next;\n    }\n    return values;\n  }\n}\n\nfunction insertAtIndex(values, index, value) {\n  const list = new LinkedList();\n  for (const item of values) {\n    list.append(item);\n  }\n  const done = list.insertAt(index, value);\n  return [done, list.toArray(), list.size];\n}",
